def sha(path):
    h=hashlib.sha256()
    with Path(path).open('rb') as f:
        for chunk in iter(lambda:f.read(1024*1024), b''): h.update(chunk)
    return h.hexdigest()

class HashReader:
    def __init__(self, stream): self.stream=stream; self.digest=hashlib.sha256(); self.count=0
    def read(self, size=-1):
        data=self.stream.read(size); self.digest.update(data); self.count+=len(data); return data

def pack(items, output):
    output=Path(output)
    output.mkdir(parents=True, exist_ok=False)
    partial=output/'nus-1080772-closeout.tar.gz.partial'
    records=[]; names=set()
    try:
        with tarfile.open(partial, 'w:gz', compresslevel=1) as archive:
            for item in items:
                name=item['destination']; rel=Path(name)
                if rel.is_absolute() or '..' in rel.parts or name in names: raise ValueError('Unsafe/duplicate destination')
                names.add(name); source=Path(item['source'])
                with source.open('rb') as stream:
                    before=os.fstat(stream.fileno())
                    info=tarfile.TarInfo('payload/'+name); info.size=before.st_size; info.mtime=int(before.st_mtime); info.mode=0o600
                    reader=HashReader(stream); archive.addfile(info,reader); after=os.fstat(stream.fileno())
                if (before.st_size,before.st_mtime_ns,before.st_ino)!=(after.st_size,after.st_mtime_ns,after.st_ino): raise RuntimeError('Source changed: '+str(source))
                digest=reader.digest.hexdigest()
                if reader.count!=before.st_size: raise RuntimeError('Incomplete source read')
                if item.get('sha256') and digest!=item['sha256']: raise RuntimeError('Pinned SHA mismatch: '+str(source))
                records.append(dict(path=name,bytes=reader.count,sha256=digest,source=str(source)))
                print('packed',name,reader.count,flush=True)
            data=json.dumps(dict(schema='hsai.closeout_bundle/v1',job=1080772,files=records),ensure_ascii=False,indent=2).encode('utf-8')
            info=tarfile.TarInfo('bundle-manifest.json'); info.size=len(data); info.mode=0o600; archive.addfile(info,io.BytesIO(data))
        final=output/'nus-1080772-closeout.tar.gz'; partial.rename(final)
        digest=sha(final)
        (output/'nus-1080772-closeout.tar.gz.sha256').write_text(digest+'  '+final.name+'\n',encoding='ascii')
        print(json.dumps(dict(complete=True,archive=str(final),sha256=digest,bytes=final.stat().st_size,files=len(records))),flush=True)
    except Exception:
        print('FAILED: partial evidence retained at '+str(output),flush=True)
        raise

if __name__=='__main__':
    p=argparse.ArgumentParser(); p.add_argument('--out',required=True,type=Path); a=p.parse_args()
    if not os.environ.get('SLURM_JOB_ID'): p.error('Run in a Slurm CPU allocation, not on login node')
    state=Path('/home/h/hengzhi/projects/HSRL/personal/runs/nus-4159-economy-long-002/status.json')
    status=json.loads(state.read_text())
    if status.get('state')!='paused' or status.get('latest',{}).get('version')!=7710: raise RuntimeError('Expected paused7710; re-inventory instead of packing changing data')
    pack(SPEC['items'], a.out)
